FUNCTION_BLOCK FB_Task
VAR_INPUT
    ipText : STRING(254);
END_VAR
VAR_OUTPUT
    ipValue : UDINT;
END_VAR
VAR
    visibleLen : INT;
    i : INT;
    c : BYTE; // or STRING(1)
    valid : BOOL;
    segCount : INT;
    segValue : UDINT;
    digitSeen : BOOL;
    octets : ARRAY[0..3] OF UDINT;
    pendingValue : UDINT;
