Implementation:

ipValue := 0; // initial safety
pendingValue := 0;
valid := FALSE;
visibleLen := LEN(ipText);
IF visibleLen <= 0 OR visibleLen > 254 THEN
    ipValue := 0;
    RETURN; // Does CODESYS allow RETURN in FB? Yes.
END_IF;

segCount := 0;
segValue := 0;
digitSeen := FALSE;
octets[0] := 0; ... // maybe reset.

FOR i := 1 TO visibleLen DO
    c := ipText[i]; // if accepted
    IF (c >= 48) AND (c <= 57) THEN
        IF segCount > 3 THEN valid:=FALSE; EXIT; END_IF;
        digitSeen := TRUE;
        segValue := segValue * 10 + TO_UDINT(c - 48);
        IF segValue > 255 THEN
            valid := FALSE;
            EXIT;
        END_IF;
    ELSIF c = 46 THEN // '.'
        IF NOT digitSeen OR segCount >= 3 THEN // if current segment empty or too many periods
            valid := FALSE;
            EXIT;
        END_IF;
        octets[segCount] := segValue;
        segCount := segCount + 1;
        segValue := 0;
        digitSeen := FALSE;
    ELSE
        valid := FALSE;
        EXIT;
    END_IF;
END_FOR;

